def choose_move(observation):
    def is_num(v):
        return isinstance(v, (int, float)) and not isinstance(v, bool)

    def as_pos(v):
        if isinstance(v, dict):
            if "x" in v and "y" in v and is_num(v.get("x")) and is_num(v.get("y")):
                return [v.get("x"), v.get("y")]
            if "pos" in v:
                p = as_pos(v.get("pos"))
                if p is not None:
                    return p
            if "position" in v:
                p = as_pos(v.get("position"))
                if p is not None:
                    return p
        if isinstance(v, (list, tuple)) and len(v) >= 2 and is_num(v[0]) and is_num(v[1]):
            return [v[0], v[1]]
        return None

    def key_has(k, words):
        s = str(k).lower()
        for w in words:
            if w in s:
                return True
        return False

    def collect_positions(obj, words):
        out = []
        if isinstance(obj, dict):
            for k, v in obj.items():
                if key_has(k, words):
                    p = as_pos(v)
                    if p is not None:
                        out.append(p)
                    else:
                        out.extend(collect_positions(v, words))
                else:
                    out.extend(collect_positions(v, words))
        elif isinstance(obj, (list, tuple)):
            for v in obj:
                p = as_pos(v)
                if p is not None:
                    out.append(p)
                else:
                    out.extend(collect_positions(v, words))
        return out

    def first_pos(obj):
        p = as_pos(obj)
        if p is not None:
            return p
        if isinstance(obj, dict):
            for v in obj.values():
                p = first_pos(v)
                if p is not None:
                    return p
        elif isinstance(obj, (list, tuple)):
            for v in obj:
                p = first_pos(v)
                if p is not None:
                    return p
        return None

    obs = observation if isinstance(observation, dict) else {}

    me = None
    for k in ("self", "me", "agent", "player", "unit"):
        if k in obs:
            me = as_pos(obs.get(k))
            if me is None:
                me = first_pos(obs.get(k))
            if me is not None:
                break
    if me is None:
        for k in obs.keys():
            if key_has(k, ("self", "me", "agent", "player", "unit", "pos", "position")):
                me = as_pos(obs.get(k))
                if me is None:
                    me = first_pos(obs.get(k))
                if me is not None:
                    break
    if me is None:
        me = [0, 0]

    resources = []
    for words in (("resource", "resources", "food", "coin", "gem", "item", "loot"),):
        resources.extend(collect_positions(obs, words))

    enemies = []
    for words in (("enemy", "opponent", "foe", "enemy_pos", "adversary", "enemypos"),):
        enemies.extend(collect_positions(obs, words))

    territory = []
    for words in (("territory", "zone", "capture", "goal", "flag", "base", "cell", "owned", "unowned", "neutral"),):
        territory.extend(collect_positions(obs, words))

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    moves = [(-1, -1), (-1, 0), (-1, 1), (0, -1), (0, 0), (0, 1), (1, -1), (1, 0), (1, 1)]

    target = None
    mode = 0  # 1 attract, -1 repel
    if resources:
        target = min(resources, key=lambda p: manhattan(me, p))
        mode = 1
    elif territory:
        target = min(territory, key=lambda p: manhattan(me, p))
        mode = 1
    elif enemies:
        target = min(enemies, key=lambda p: manhattan(me, p))
        mode = -1

    best = [0, 0]
    best_score = None

    for dx, dy in moves:
        nx = me[0] + dx
        ny = me[1] + dy
        score = 0.0

        if target is not None:
            d = manhattan([nx, ny], target)
            if mode > 0:
                score -= d
            else:
                score += d * 2

        if resources:
            dr = min(manhattan([nx, ny], p) for p in resources)
            score -= 0.6 * dr
        if territory:
            dt = min(manhattan([nx, ny], p) for p in territory)
            score -= 0.2 * dt
        if enemies:
            de = min(manhattan([nx, ny], p) for p in enemies)
            score += 0.8 * max(0, 3 - de)
            score += 0.1 * de

        if dx == 0 and dy == 0:
            score -= 0.05

        if best_score is None or score > best_score or (score == best_score and (dx, dy) < (best[0], best[1])):
            best_score = score
            best = [dx, dy]

    if best[0] < -1:
        best[0] = -1
    if best[0] > 1:
        best[0] = 1
    if best[1] < -1:
        best[1] = -1
    if best[1] > 1:
        best[1] = 1
    return best

